// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** An ER visit: the patient, the arrival, the latest triage, the stage, the medico-legal checklist and case, and how the patient left (MSDS 20). */
export interface ErVisitOut {
  er_visit_id: number;
  /** The ER register number, e.g. ER-2026-000042 */
  er_number: string;
  patient_id: number;
  mrn: string;
  patient_name: string;
  gender: "male" | "female" | "other" | "unknown" | null;
  age_years: number | null;
  /** The emergency ticket (billing), once issued */
  ticket_id: number | null;
  ticket_number: string | null;
  ticket_status: "Issued" | "Waiting" | "InConsultation" | "Examined" | "Completed" | "Deferred" | "Expired" | "Forfeited" | "Refunded" | "Void" | "Cancelled" | null;
  /** Code Red, or the admission requested from the ER */
  admission_id: number | null;
  admission_number: string | null;
  admission_status: "AdmissionPending" | "Waitlisted" | "BedReserved" | "CodeRedActive" | "Admitted" | "DischargeInProgress" | "Discharged" | "Cancelled" | null;
  ward_name: string | null;
  arrived_at: string;
  arrival_mode: "WalkIn" | "Ambulance" | "Rescue1122" | "Police" | "Referred" | null;
  referred_from: string | null;
  presenting_complaint: string | null;
  stage: "Arrived" | "Triaged" | "InTreatment" | "Observation" | "AwaitingAdmission" | "AwaitingBed" | "AwaitingReferral" | "Departed";
  stage_since: string;
  /** 1 (resuscitation) … 5 (non-urgent); null: not triaged yet */
  triage_level: number | null;
  triage_level_name: string | null;
  triage_colour: "Red" | "Orange" | "Yellow" | "Green" | "Blue" | "White" | "Black" | null;
  /** The level's target time from triage to the doctor */
  triage_target_minutes: number | null;
  /** The first triage */
  triaged_at: string | null;
  /** First seen by a doctor (called in, or taken for treatment) */
  seen_at: string | null;
  seen_by: number | null;
  seen_by_name: string | null;
  /** The medico-legal checklist; null: not decided yet */
  is_medico_legal: boolean | null;
  mlc_case_type_id: number | null;
  mlc_case_type_name: string | null;
  /** The medico-legal case opened for this visit */
  mlc_id: number | null;
  mlc_number: string | null;
  disposition: "Admitted" | "Discharged" | "Referred" | "LAMA" | "DischargedOnRequest" | "LeftWithoutBeingSeen" | "Died" | "BroughtDead" | null;
  departed_at: string | null;
  condition_at_departure: "Improved" | "Stable" | "Unchanged" | "Deteriorated" | "Critical" | null;
  follow_up_advice: string | null;
  referral_reason: string | null;
  referred_to: string | null;
  statement_signed_by: string | null;
  absence_noticed_at: string | null;
  death_id: number | null;
  death_number: string | null;
  departure_note: string | null;
  /** Who recorded the departure (MSDS 147) */
  departure_stamp: AuthorStampOut | null;
  created_at: string;
  created_by_name: string;
  /** When the visit first waited for an admission */
  admission_decided_at: string | null;
  /** What is overdue by the hospital's targets (settings er_*), and a medico-legal checklist still to answer */
  flags: ("TriageOverdue" | "DoctorOverdue" | "ObservationTooLong" | "AdmissionWaitTooLong" | "ReferralWaitTooLong" | "MlcNotOpened" | "MedicoLegalUndecided")[];
  minutes_in_er: number;
  minutes_in_stage: number | null;
}

/** The author stamp of a clinical entry (MSDS IMS 147), as the author's staff record stood when they signed it (SQL hms_author_stamp / hms_employee_stamp, migration 0013 [STP]). Show it under the entry on screen and print `text` under it on paper. */
export interface AuthorStampOut {
  employee_id: number | null;
  user_id: number | null;
  name: string;
  /** Designation and specialty, e.g. "Medical Officer, General Medicine" */
  designation: string | null;
  /** Council registration, e.g. "PMDC 12345-P" or "PNC 67890" */
  registration: string | null;
  /** When the entry was signed, reported or verified */
  at: string;
  /** The printed line: name, designation, registration, date and time */
  text: string;
}

