/** One triage of the visit, with the algorithm as it applied (MSDS 18). */
export interface ErTriageOut {
  assessment_id: number;
  assessed_at: string;
  presenting_complaint: string;
  heart_rate: number | null;
  respiratory_rate: number | null;
  bp_systolic: number | null;
  bp_diastolic: number | null;
  spo2: number | null;
  temp_c: number | null;
  gcs: number | null;
  pain_score: number | null;
  blood_glucose: number | null;
  /** Every danger sign ticked and vital-sign limit met */
  matched: ErTriageMatchOut[];
  suggested_level: number;
  assigned_level: number;
  assigned_level_name: string;
  assigned_colour: "Red" | "Orange" | "Yellow" | "Green" | "Blue" | "White" | "Black";
  override_reason: string | null;
  is_medico_legal: boolean | null;
  mlc_case_type_id: number | null;
  mlc_case_type_name: string | null;
  author_stamp: AuthorStampOut;
}

export interface ErTriageMatchOut {
  discriminator_id: number | null;
  level: number;
  kind: "Sign" | "VitalSign" | "CodeRed";
  label: string;
}

export interface ErStageLogOut {
  from_stage: "Arrived" | "Triaged" | "InTreatment" | "Observation" | "AwaitingAdmission" | "AwaitingBed" | "AwaitingReferral" | "Departed" | null;
  to_stage: "Arrived" | "Triaged" | "InTreatment" | "Observation" | "AwaitingAdmission" | "AwaitingBed" | "AwaitingReferral" | "Departed";
  at: string;
  note: string | null;
  by_name: string | null;
}

/** The ER register (emergency log book) — GET /api/v1/er/visits (who may call: holders of er.visit.view). */
export function listVisitsEr(query?: { date_from?: string | null; date_to?: string | null; disposition?: "Admitted" | "Discharged" | "Referred" | "LAMA" | "DischargedOnRequest" | "LeftWithoutBeingSeen" | "Died" | "BroughtDead" | null; triage_level?: number | null; open_only?: boolean; patient_id?: number | null; limit?: number }): Promise<ErVisitOut[]> {
  return api<ErVisitOut[]>("GET", withQuery(`/er/visits`, query), undefined);
}

/** One ER visit — GET /api/v1/er/visits/{er_visit_id} (who may call: holders of er.visit.view). */
export function getVisit(er_visit_id: number): Promise<ErVisitDetailOut> {
  return api<ErVisitDetailOut>("GET", `/er/visits/${er_visit_id}`, undefined);
}
